mapper.select:
SELECT r.*
FROM requirements r
WHERE r.deleted_at = 0
  AND r.is_draft = 1
  AND r.last_saved_at IS NOT NULL
  AND r.creator_id = #{userId}
   AND r.project_id = #{projectId} 
   AND r.type = #{type} 
   AND r.priority = #{priority} 
   AND r.node_status = #{nodeStatus} 
   AND r.node_status NOT IN (SELECT code FROM node_statuses WHERE is_end = 1) AND r.due_date IS NOT NULL AND r.due_date < CURDATE() 
   AND r.status = #{status} 
   AND r.assignee_id = #{assigneeId} 


ORDER BY r.updated_at DESC, r.id DESC

SELECT DISTINCT r.*
FROM requirements r
JOIN workflow_instances wi ON wi.id = r.workflow_instance_id
JOIN workflow_nodes wn ON wn.workflow_version_id = wi.workflow_version_id AND wn.node_id = wi.current_node_id
WHERE r.deleted_at = 0
  AND r.is_draft = 0
  AND wi.status = 'running'
  AND wn.assignee_type IS NOT NULL
  AND wn.assignee_type != ''

      AND r.org_id IN

          #{orgId}


   AND r.project_id = #{projectId} 
   AND r.type = #{type} 
   AND r.priority = #{priority} 
   AND r.status = #{status} 
   AND r.assignee_id = #{assigneeId} 


  AND (
    (wn.assignee_type = 'SPECIFIED_USER' AND wn.assignee_user_ids IS NOT NULL
        AND JSON_CONTAINS(wn.assignee_user_ids, CAST(#{userId} AS JSON)))

      OR (wn.assignee_type = 'SPECIFIED_ROLE' AND EXISTS (
        SELECT 1 FROM roles rr
        WHERE rr.id = wn.assignee_role_id
          AND rr.deleted_at = 0
          AND (rr.code IN

            #{rc}

          OR rr.name IN

            #{roleName}
          )
      ))
      OR (wn.assignee_type = 'SPECIFIED_ROLE_GROUP' AND EXISTS (
        SELECT 1 FROM roles rg
        WHERE rg.role_group_id = wn.assignee_role_group_id
          AND rg.deleted_at = 0
          AND (rg.code IN

            #{groupRoleCode}

          OR rg.name IN

            #{groupRoleName}
          )
      ))


      OR (wn.assignee_type = 'SPECIFIED_ORG' AND (
        (COALESCE(JSON_UNQUOTE(JSON_EXTRACT(wn.properties, '$.orgScopeType')), 'include_children') = 'current'
          AND wn.assignee_org_id IN

            #{orgId}

        )

          OR (COALESCE(JSON_UNQUOTE(JSON_EXTRACT(wn.properties, '$.orgScopeType')), 'include_children') != 'current'
            AND wn.assignee_org_id IN

              #{scopedOrgId}

          )

      ))

    OR (wn.assignee_type = 'PREV_APPROVER' AND #{userId} = (
      SELECT wit.operator_id FROM workflow_instance_transitions wit
      WHERE wit.instance_id = wi.id
        AND wit.to_node_id = wi.current_node_id
      ORDER BY wit.id DESC
      LIMIT 1
    ))
    OR (wn.assignee_type = 'CREATOR' AND r.creator_id = #{userId})
  )
ORDER BY r.updated_at DESC, r.id DESC

SELECT r.*
FROM requirement_follows rf
JOIN requirements r ON r.id = rf.requirement_id
WHERE rf.user_id = #{userId}
  AND r.deleted_at = 0
  AND r.is_draft = 0
   AND r.project_id = #{projectId} 
   AND r.type = #{type} 
   AND r.priority = #{priority} 
   AND r.node_status = #{nodeStatus} 
   AND r.node_status NOT IN (SELECT code FROM node_statuses WHERE is_end = 1) AND r.due_date IS NOT NULL AND r.due_date < CURDATE() 
   AND r.status = #{status} 
   AND r.assignee_id = #{assigneeId} 





        AND r.org_id IN

          #{orgId}



        AND r.creator_id = #{userId}



ORDER BY rf.created_at DESC, rf.id DESC

SELECT r.*
FROM requirements r
WHERE EXISTS (
    SELECT 1
    FROM requirement_pending_tasks pt
    WHERE pt.task_type = 'CC_READ_ONLY'
      AND pt.user_id = #{userId}
      AND pt.requirement_id = r.id
)
  AND r.deleted_at = 0
  AND r.is_draft = 0

      AND r.org_id IN

          #{orgId}


   AND r.project_id = #{projectId} 
   AND r.type = #{type} 
   AND r.priority = #{priority} 
   AND r.node_status = #{nodeStatus} 
   AND r.node_status NOT IN (SELECT code FROM node_statuses WHERE is_end = 1) AND r.due_date IS NOT NULL AND r.due_date < CURDATE() 
   AND r.status = #{status} 
   AND r.assignee_id = #{assigneeId} 


ORDER BY (
    SELECT MAX(pt_sort.updated_at)
    FROM requirement_pending_tasks pt_sort
    WHERE pt_sort.task_type = 'CC_READ_ONLY'
      AND pt_sort.requirement_id = r.id
      AND pt_sort.user_id = #{userId}
) DESC, r.id DESC

SELECT DISTINCT r.*
FROM requirements r
WHERE r.deleted_at = 0
  AND r.is_draft = 0

      AND r.org_id IN

          #{orgId}


   AND r.project_id = #{projectId} 
   AND r.type = #{type} 
   AND r.priority = #{priority} 
   AND r.status = #{status} 
   AND r.assignee_id = #{assigneeId} 
  AND (
    r.creator_id = #{userId}
    OR EXISTS (
      SELECT 1 FROM workflow_instance_transitions wit
      WHERE wit.requirement_id = r.id AND wit.operator_id = #{userId}
    )
  )
  AND NOT EXISTS (
    SELECT 1
    FROM workflow_instances wi2
    JOIN workflow_nodes wn2 ON wn2.workflow_version_id = wi2.workflow_version_id AND wn2.node_id = wi2.current_node_id
    WHERE wi2.id = r.workflow_instance_id
      AND wi2.status = 'running'
      AND wn2.assignee_type IS NOT NULL
      AND wn2.assignee_type != ''
      AND (
        (wn2.assignee_type = 'SPECIFIED_USER' AND wn2.assignee_user_ids IS NOT NULL
            AND JSON_CONTAINS(wn2.assignee_user_ids, CAST(#{userId} AS JSON)))

          OR (wn2.assignee_type = 'SPECIFIED_ROLE' AND EXISTS (
            SELECT 1 FROM roles rr2
            WHERE rr2.id = wn2.assignee_role_id
              AND rr2.deleted_at = 0
              AND (rr2.code IN

                #{rc}

              OR rr2.name IN

                #{roleName}
              )
          ))
          OR (wn2.assignee_type = 'SPECIFIED_ROLE_GROUP' AND EXISTS (
            SELECT 1 FROM roles rg2
            WHERE rg2.role_group_id = wn2.assignee_role_group_id
              AND rg2.deleted_at = 0
              AND (rg2.code IN

                #{groupRoleCode}

              OR rg2.name IN

                #{groupRoleName}
              )
          ))


          OR (wn2.assignee_type = 'SPECIFIED_ORG' AND (
            (COALESCE(JSON_UNQUOTE(JSON_EXTRACT(wn2.properties, '$.orgScopeType')), 'include_children') = 'current'
              AND wn2.assignee_org_id IN

                #{orgId}

            )

              OR (COALESCE(JSON_UNQUOTE(JSON_EXTRACT(wn2.properties, '$.orgScopeType')), 'include_children') != 'current'
                AND wn2.assignee_org_id IN

                  #{scopedOrgId}

              )

          ))

        OR (wn2.assignee_type = 'PREV_APPROVER' AND #{userId} = (
          SELECT wit2.operator_id FROM workflow_instance_transitions wit2
          WHERE wit2.instance_id = wi2.id
            AND wit2.to_node_id = wi2.current_node_id
          ORDER BY wit2.id DESC
          LIMIT 1
        ))
        OR (wn2.assignee_type = 'CREATOR' AND r.creator_id = #{userId})
      )
  )


ORDER BY r.updated_at DESC

SELECT DISTINCT r.*
FROM requirements r
JOIN requirement_pending_tasks pt ON pt.requirement_id = r.id
WHERE pt.task_type = 'APPROVAL'
  AND pt.user_id = #{userId}
  AND r.deleted_at = 0
  AND r.is_draft = 0

      AND r.org_id IN

          #{orgId}


   AND r.project_id = #{projectId} 
   AND r.type = #{type} 
   AND r.priority = #{priority} 
   AND r.status = #{status} 
   AND r.assignee_id = #{assigneeId} 


 ORDER BY pt.updated_at DESC, r.id DESC

SELECT r.* FROM requirements r INNER JOIN workflow_instances wi ON r.workflow_instance_id = wi.id WHERE r.deleted_at = 0 AND r.is_draft = 0
AND r.org_id IN
#{orgId}
AND wi.status = 'running' AND EXISTS ( SELECT 1 FROM requirement_pending_tasks pt LEFT JOIN roles direct_role ON pt.role_id IS NOT NULL AND direct_role.id = pt.role_id AND direct_role.deleted_at = 0 LEFT JOIN roles rg_role ON pt.role_group_id IS NOT NULL AND rg_role.role_group_id = pt.role_group_id AND rg_role.deleted_at = 0 LEFT JOIN sys_org pt_org ON pt.org_id IS NOT NULL AND pt_org.id = pt.org_id AND pt_org.deleted_at = 0 LEFT JOIN users login_user ON login_user.id = #{userId} LEFT JOIN user_organizations uo ON uo.user_id = #{userId} WHERE pt.task_type = 'APPROVAL' AND pt.requirement_id = r.id AND pt.workflow_instance_id = wi.id AND pt.current_node_id = wi.current_node_id AND ( pt.user_id = #{userId} OR ( NOT EXISTS ( SELECT 1 FROM requirement_pending_tasks direct_pt WHERE direct_pt.task_type = 'APPROVAL' AND direct_pt.requirement_id = r.id AND direct_pt.workflow_instance_id = wi.id AND direct_pt.current_node_id = wi.current_node_id AND direct_pt.user_id IS NOT NULL ) AND (
direct_role.id IN
#{rid}
OR rg_role.id IN
#{rid2}
1 = 0
OR ( pt.org_id IS NOT NULL AND pt_org.id IS NOT NULL AND ( login_user.org_id = pt.org_id OR login_user.department_id = pt.org_id OR login_user.region_id = pt.org_id OR uo.org_id = pt.org_id OR uo.department_id = pt.org_id OR uo.region_id = pt.org_id OR EXISTS ( SELECT 1 FROM sys_org user_org WHERE user_org.deleted_at = 0 AND user_org.id IN ( login_user.org_id, login_user.department_id, login_user.region_id, uo.org_id, uo.department_id, uo.region_id ) AND user_org.path LIKE CONCAT(pt_org.path, '%') ) ) ) ) ) ) ) AND r.project_id = #{projectId} AND r.type = #{type} AND r.priority = #{priority} AND r.node_status = #{nodeStatus} AND r.node_status NOT IN (SELECT code FROM node_statuses WHERE is_end = 1) AND r.due_date IS NOT NULL AND r.due_date < CURDATE() AND r.status = #{status} AND r.assignee_id = #{assigneeId}
ORDER BY COALESCE(( SELECT MAX(pt_sort.updated_at) FROM requirement_pending_tasks pt_sort WHERE pt_sort.task_type = 'APPROVAL' AND pt_sort.requirement_id = r.id AND pt_sort.workflow_instance_id = wi.id AND pt_sort.current_node_id = wi.current_node_id ), r.updated_at) DESC, r.id DESC

SELECT r.* FROM requirements r WHERE r.deleted_at = 0 AND r.is_draft = 0
AND r.org_id IN
#{orgId}
AND ( r.creator_id = #{userId} OR EXISTS ( SELECT 1 FROM workflow_instance_transitions wit WHERE wit.requirement_id = r.id AND wit.operator_id = #{userId} ) ) AND NOT EXISTS ( SELECT 1 FROM workflow_instances wi2 WHERE wi2.id = r.workflow_instance_id AND wi2.status = 'running' AND EXISTS ( SELECT 1 FROM requirement_pending_tasks pt LEFT JOIN roles direct_role ON pt.role_id IS NOT NULL AND direct_role.id = pt.role_id AND direct_role.deleted_at = 0 LEFT JOIN roles rg_role ON pt.role_group_id IS NOT NULL AND rg_role.role_group_id = pt.role_group_id AND rg_role.deleted_at = 0 LEFT JOIN sys_org pt_org ON pt.org_id IS NOT NULL AND pt_org.id = pt.org_id AND pt_org.deleted_at = 0 LEFT JOIN users login_user ON login_user.id = #{userId} LEFT JOIN user_organizations uo ON uo.user_id = #{userId} WHERE pt.task_type = 'APPROVAL' AND pt.requirement_id = r.id AND pt.workflow_instance_id = wi2.id AND pt.current_node_id = wi2.current_node_id AND ( pt.user_id = #{userId} OR ( NOT EXISTS ( SELECT 1 FROM requirement_pending_tasks direct_pt WHERE direct_pt.task_type = 'APPROVAL' AND direct_pt.requirement_id = r.id AND direct_pt.workflow_instance_id = wi2.id AND direct_pt.current_node_id = wi2.current_node_id AND direct_pt.user_id IS NOT NULL ) AND (
direct_role.id IN
