1 = 0
OR ( pt.org_id IS NOT NULL AND pt_org.id IS NOT NULL AND ( login_user.org_id = pt.org_id OR login_user.department_id = pt.org_id OR login_user.region_id = pt.org_id OR uo.org_id = pt.org_id OR uo.department_id = pt.org_id OR uo.region_id = pt.org_id OR EXISTS ( SELECT 1 FROM sys_org user_org WHERE user_org.deleted_at = 0 AND user_org.id IN ( login_user.org_id, login_user.department_id, login_user.region_id, uo.org_id, uo.department_id, uo.region_id ) AND user_org.path LIKE CONCAT(pt_org.path, '%') ) ) ) ) ) ) ) ) AND r.project_id = #{projectId} AND r.type = #{type} AND r.priority = #{priority} AND r.node_status = #{nodeStatus} AND r.node_status NOT IN (SELECT code FROM node_statuses WHERE is_end = 1) AND r.due_date IS NOT NULL AND r.due_date < CURDATE() AND r.status = #{status} AND r.assignee_id = #{assigneeId}
ORDER BY r.updated_at DESC

SELECT DISTINCT r.*
FROM requirements r
WHERE r.deleted_at = 0

  AND r.id IN (
      -- 草稿（仅创建人可见）
      SELECT r2.id FROM requirements r2
      WHERE r2.deleted_at = 0 AND r2.is_draft = 1 AND r2.creator_id = #{userId}
       AND r2.project_id = #{projectId} 
       AND r2.type = #{type} 
       AND r2.priority = #{priority} 
       AND r2.status = #{status} 
       AND r2.node_status = #{nodeStatus} 
       AND r2.node_status NOT IN (SELECT code FROM node_statuses WHERE is_end = 1) AND r2.due_date IS NOT NULL AND r2.due_date < CURDATE() 
       AND r2.assignee_id = #{assigneeId} 


              AND r2.title LIKE CONCAT('%', #{keyword}, '%')
              AND r2.requirement_no LIKE CONCAT('%', #{keyword}, '%')
              AND r2.description LIKE CONCAT('%', #{keyword}, '%')
              AND EXISTS (SELECT 1 FROM users kwa WHERE kwa.id = r2.assignee_id AND kwa.deleted_at = 0 AND kwa.real_name LIKE CONCAT('%', #{keyword}, '%'))
              AND EXISTS (SELECT 1 FROM requirement_comments kc WHERE kc.requirement_id = r2.id AND kc.content LIKE CONCAT('%', #{keyword}, '%'))
              AND (r2.title LIKE CONCAT('%', #{keyword}, '%') OR r2.description LIKE CONCAT('%', #{keyword}, '%'))


      UNION
      -- 待办：当前节点为我处理（含角色/组织/创建人/上一审批人）
      SELECT DISTINCT r2.id FROM requirements r2
      JOIN workflow_instances wi ON wi.id = r2.workflow_instance_id AND wi.status = 'running'
      JOIN workflow_nodes wn ON wn.workflow_version_id = wi.workflow_version_id AND wn.node_id = wi.current_node_id
      WHERE r2.deleted_at = 0 AND r2.is_draft = 0 AND wn.assignee_type IS NOT NULL AND wn.assignee_type != ''

          AND r2.org_id IN
          #{orgId}

       AND r2.project_id = #{projectId} 
       AND r2.type = #{type} 
       AND r2.priority = #{priority} 
       AND r2.status = #{status} 
       AND r2.assignee_id = #{assigneeId} 
       AND r2.node_status = #{nodeStatus} 
       AND r2.node_status NOT IN (SELECT code FROM node_statuses WHERE is_end = 1) AND r2.due_date IS NOT NULL AND r2.due_date < CURDATE() 


              AND r2.title LIKE CONCAT('%', #{keyword}, '%')
              AND r2.requirement_no LIKE CONCAT('%', #{keyword}, '%')
              AND r2.description LIKE CONCAT('%', #{keyword}, '%')
              AND EXISTS (SELECT 1 FROM users kwa WHERE kwa.id = r2.assignee_id AND kwa.deleted_at = 0 AND kwa.real_name LIKE CONCAT('%', #{keyword}, '%'))
              AND EXISTS (SELECT 1 FROM requirement_comments kc WHERE kc.requirement_id = r2.id AND kc.content LIKE CONCAT('%', #{keyword}, '%'))
              AND (r2.title LIKE CONCAT('%', #{keyword}, '%') OR r2.description LIKE CONCAT('%', #{keyword}, '%'))


      AND (
          (wn.assignee_type = 'SPECIFIED_USER' AND wn.assignee_user_ids IS NOT NULL
              AND JSON_CONTAINS(wn.assignee_user_ids, CAST(#{userId} AS JSON)))

            OR (wn.assignee_type = 'SPECIFIED_ROLE' AND EXISTS (
              SELECT 1 FROM roles rr WHERE rr.id = wn.assignee_role_id AND rr.deleted_at = 0
                AND (rr.code IN #{rc}
                   OR rr.name IN #{roleName})
            ))
            OR (wn.assignee_type = 'SPECIFIED_ROLE_GROUP' AND EXISTS (
              SELECT 1 FROM roles rg WHERE rg.role_group_id = wn.assignee_role_group_id AND rg.deleted_at = 0
                AND (rg.code IN #{groupRoleCode}
                   OR rg.name IN #{groupRoleName})
            ))


            OR (wn.assignee_type = 'SPECIFIED_ORG' AND (
              (COALESCE(JSON_UNQUOTE(JSON_EXTRACT(wn.properties, '$.orgScopeType')), 'include_children') = 'current'
                AND wn.assignee_org_id IN #{orgId})

                OR (COALESCE(JSON_UNQUOTE(JSON_EXTRACT(wn.properties, '$.orgScopeType')), 'include_children') != 'current'
                  AND wn.assignee_org_id IN #{scopedOrgId})

            ))

          OR (wn.assignee_type = 'PREV_APPROVER' AND #{userId} = (
              SELECT wit.operator_id FROM workflow_instance_transitions wit
              WHERE wit.instance_id = wi.id AND wit.to_node_id = wi.current_node_id
              ORDER BY wit.id DESC LIMIT 1))
          OR (wn.assignee_type = 'CREATOR' AND r2.creator_id = #{userId})
      )
      UNION
      -- 已办：创建或审批过，且当前不在我待办的节点
      SELECT DISTINCT r2.id FROM requirements r2
      WHERE r2.deleted_at = 0 AND r2.is_draft = 0

          AND r2.org_id IN
          #{orgId}

       AND r2.project_id = #{projectId} 
       AND r2.type = #{type} 
       AND r2.priority = #{priority} 
       AND r2.status = #{status} 
       AND r2.assignee_id = #{assigneeId} 
       AND r2.node_status = #{nodeStatus} 
       AND r2.node_status NOT IN (SELECT code FROM node_statuses WHERE is_end = 1) AND r2.due_date IS NOT NULL AND r2.due_date < CURDATE() 


              AND r2.title LIKE CONCAT('%', #{keyword}, '%')
              AND r2.requirement_no LIKE CONCAT('%', #{keyword}, '%')
              AND r2.description LIKE CONCAT('%', #{keyword}, '%')
              AND EXISTS (SELECT 1 FROM users kwa WHERE kwa.id = r2.assignee_id AND kwa.deleted_at = 0 AND kwa.real_name LIKE CONCAT('%', #{keyword}, '%'))
              AND EXISTS (SELECT 1 FROM requirement_comments kc WHERE kc.requirement_id = r2.id AND kc.content LIKE CONCAT('%', #{keyword}, '%'))
              AND (r2.title LIKE CONCAT('%', #{keyword}, '%') OR r2.description LIKE CONCAT('%', #{keyword}, '%'))


      AND (
          r2.creator_id = #{userId}
          OR EXISTS (SELECT 1 FROM workflow_instance_transitions wit WHERE wit.requirement_id = r2.id AND wit.operator_id = #{userId})
      )
      AND NOT EXISTS (
          SELECT 1 FROM workflow_instances wi2
          JOIN workflow_nodes wn2 ON wn2.workflow_version_id = wi2.workflow_version_id AND wn2.node_id = wi2.current_node_id
          WHERE wi2.id = r2.workflow_instance_id AND wi2.status = 'running' AND wn2.assignee_type IS NOT NULL
            AND wn2.assignee_type != ''
            AND (
                (wn2.assignee_type = 'SPECIFIED_USER' AND wn2.assignee_user_ids IS NOT NULL
                    AND JSON_CONTAINS(wn2.assignee_user_ids, CAST(#{userId} AS JSON)))

                  OR (wn2.assignee_type = 'SPECIFIED_ROLE' AND EXISTS (
                    SELECT 1 FROM roles rr WHERE rr.id = wn2.assignee_role_id AND rr.deleted_at = 0
                      AND (rr.code IN #{rc}
                         OR rr.name IN #{roleName})
                  ))
                  OR (wn2.assignee_type = 'SPECIFIED_ROLE_GROUP' AND EXISTS (
                    SELECT 1 FROM roles rg WHERE rg.role_group_id = wn2.assignee_role_group_id AND rg.deleted_at = 0
                      AND (rg.code IN #{groupRoleCode}
                         OR rg.name IN #{groupRoleName})
                  ))


                  OR (wn2.assignee_type = 'SPECIFIED_ORG' AND (
                      (COALESCE(JSON_UNQUOTE(JSON_EXTRACT(wn2.properties, '$.orgScopeType')), 'include_children') = 'current'
                          AND wn2.assignee_org_id IN #{orgId})

                          OR (COALESCE(JSON_UNQUOTE(JSON_EXTRACT(wn2.properties, '$.orgScopeType')), 'include_children') != 'current'
                              AND wn2.assignee_org_id IN #{scopedOrgId})

                  ))

                OR (wn2.assignee_type = 'PREV_APPROVER' AND #{userId} = (
                    SELECT wit2.operator_id FROM workflow_instance_transitions wit2
                    WHERE wit2.instance_id = wi2.id AND wit2.to_node_id = wi2.current_node_id
                    ORDER BY wit2.id DESC LIMIT 1))
                OR (wn2.assignee_type = 'CREATOR' AND r2.creator_id = #{userId})
            )
      )
      UNION
      -- 关注
      SELECT r2.id FROM requirement_follows rf
      JOIN requirements r2 ON r2.id = rf.requirement_id
      WHERE rf.user_id = #{userId} AND r2.deleted_at = 0 AND r2.is_draft = 0
       AND r2.project_id = #{projectId} 
       AND r2.type = #{type} 
       AND r2.priority = #{priority} 
       AND r2.status = #{status} 
       AND r2.assignee_id = #{assigneeId} 
       AND r2.node_status = #{nodeStatus} 
       AND r2.node_status NOT IN (SELECT code FROM node_statuses WHERE is_end = 1) AND r2.due_date IS NOT NULL AND r2.due_date < CURDATE() 


              AND r2.title LIKE CONCAT('%', #{keyword}, '%')
              AND r2.requirement_no LIKE CONCAT('%', #{keyword}, '%')
              AND r2.description LIKE CONCAT('%', #{keyword}, '%')
              AND EXISTS (SELECT 1 FROM users kwa WHERE kwa.id = r2.assignee_id AND kwa.deleted_at = 0 AND kwa.real_name LIKE CONCAT('%', #{keyword}, '%'))
              AND EXISTS (SELECT 1 FROM requirement_comments kc WHERE kc.requirement_id = r2.id AND kc.content LIKE CONCAT('%', #{keyword}, '%'))
              AND (r2.title LIKE CONCAT('%', #{keyword}, '%') OR r2.description LIKE CONCAT('%', #{keyword}, '%'))





                  AND r2.org_id IN #{orgId}

              AND r2.creator_id = #{userId}


      UNION
      -- 抄送
      SELECT r2.id FROM requirements r2
      WHERE EXISTS (
          SELECT 1 FROM requirement_pending_tasks pt
          WHERE pt.task_type = 'CC_READ_ONLY' AND pt.user_id = #{userId} AND pt.requirement_id = r2.id
      ) AND r2.deleted_at = 0 AND r2.is_draft = 0

          AND r2.org_id IN
          #{orgId}

       AND r2.project_id = #{projectId} 
       AND r2.type = #{type} 
       AND r2.priority = #{priority} 
       AND r2.status = #{status} 
       AND r2.assignee_id = #{assigneeId} 
       AND r2.node_status = #{nodeStatus} 
       AND r2.node_status NOT IN (SELECT code FROM node_statuses WHERE is_end = 1) AND r2.due_date IS NOT NULL AND r2.due_date < CURDATE() 


              AND r2.title LIKE CONCAT('%', #{keyword}, '%')
              AND r2.requirement_no LIKE CONCAT('%', #{keyword}, '%')
              AND r2.description LIKE CONCAT('%', #{keyword}, '%')
              AND EXISTS (SELECT 1 FROM users kwa WHERE kwa.id = r2.assignee_id AND kwa.deleted_at = 0 AND kwa.real_name LIKE CONCAT('%', #{keyword}, '%'))
              AND EXISTS (SELECT 1 FROM requirement_comments kc WHERE kc.requirement_id = r2.id AND kc.content LIKE CONCAT('%', #{keyword}, '%'))
              AND (r2.title LIKE CONCAT('%', #{keyword}, '%') OR r2.description LIKE CONCAT('%', #{keyword}, '%'))


  )
ORDER BY r.updated_at DESC, r.id DESC
